  if ((s.w || 0) !== at[0]) { sd.L.w = s.w || 0; sd.R.w = s.w || 0; }
  if ((s.r || 0) !== at[1]) { sd.L.r = s.r > 0 ? s.r : null; sd.R.r = s.r > 0 ? s.r : null; }
  const c = sideCounted(s);
